function previewAvatar(input, targetId, isSettings){
  if(!input.files || !input.files[0]) return;
  const reader = new FileReader();
  reader.onload = e => {
    document.getElementById(targetId).src = e.target.result;
    if(isSettings && state.user){
      state.user.avatar = e.target.result;
      document.getElementById('sidebar-avatar').src = e.target.result;
    }
  };
  reader.readAsDataURL(input.files[0]);
}

/* =======================================================================
   LOGIN REAL COM GOOGLE (Google Identity Services)
   ---------------------------------------------------------------------
   Para habilitar o login/cadastro DE VERDADE com Google, você precisa:

   1) Ir em https://console.cloud.google.com/ e criar um projeto (ou usar um existente).
   2) Configurar a "Tela de consentimento OAuth" (External é suficiente para testes).
   3) Em "Credenciais" > "Criar credenciais" > "ID do cliente OAuth":
        - Tipo de aplicativo: "Aplicativo da Web"
        - Em "Origens JavaScript autorizadas", adicione o endereço EXATO de onde
          este app vai rodar. Ex: http://localhost:8000  ou  https://seusite.com
          (login do Google NÃO funciona abrindo o arquivo direto com file://,
          por isso é preciso servir os arquivos com um servidor local ou hospedagem).
   4) Copie o Client ID gerado (termina com ".apps.googleusercontent.com")
      e cole na constante abaixo.

   Enquanto o Client ID não for configurado, o app mostra um aviso e um
   botão de "conta demo" no lugar do botão real do Google.
   ======================================================================= */
const GOOGLE_CLIENT_ID = '926034754304-3445g4kqdp62m6ukdda14t17ebml1v3s.apps.googleusercontent.com';

function isGoogleConfigured(){
  return !!GOOGLE_CLIENT_ID
    && GOOGLE_CLIENT_ID.endsWith('.apps.googleusercontent.com')
    && !GOOGLE_CLIENT_ID.includes('SEU_CLIENT_ID_AQUI');
}

let googleSignInReady = false;

/* Chamado pelo atributo onload da tag <script> do Google (accounts.google.com/gsi/client) */
function onGsiLoad(){
  initGoogleSignIn();
}

function initGoogleSignIn(){
  if(googleSignInReady) return;

  if(!isGoogleConfigured()){
    document.getElementById('google-btn-login').classList.add('hidden');
    document.getElementById('google-btn-signup').classList.add('hidden');
    document.getElementById('google-warning-login').classList.remove('hidden');
    document.getElementById('google-warning-signup').classList.remove('hidden');
    return;
  }

  if(typeof google === 'undefined' || !google.accounts || !google.accounts.id){
    // A biblioteca do Google ainda não carregou; onGsiLoad() chamará de novo quando carregar.
    return;
  }

  google.accounts.id.initialize({
    client_id: GOOGLE_CLIENT_ID,
    callback: handleGoogleCredential,
    auto_select: false,
    cancel_on_tap_outside: true
  });

  document.getElementById('google-warning-login').classList.add('hidden');
  document.getElementById('google-warning-signup').classList.add('hidden');
  document.getElementById('google-btn-login').classList.remove('hidden');
  document.getElementById('google-btn-signup').classList.remove('hidden');

  google.accounts.id.renderButton(document.getElementById('google-btn-login'), {
    type:'standard', theme:'outline', size:'large', shape:'pill',
    text:'signin_with', width:320, logo_alignment:'left'
  });
  google.accounts.id.renderButton(document.getElementById('google-btn-signup'), {
    type:'standard', theme:'outline', size:'large', shape:'pill',
    text:'signup_with', width:320, logo_alignment:'left'
  });

  googleSignInReady = true;
}

function decodeJwtPayload(token){
  try{
    const base64Url = token.split('.')[1];
    const base64 = base64Url.replace(/-/g,'+').replace(/_/g,'/');
    const jsonPayload = decodeURIComponent(
      atob(base64).split('').map(c=>'%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)).join('')
    );
    return JSON.parse(jsonPayload);
  }catch(e){
    return null;
  }
}

/* Callback disparado pelo Google após o usuário fazer login de verdade.
   response.credential é um ID Token (JWT) assinado pelo Google. Em uma
   aplicação com backend, o ideal é enviar esse token para o servidor e
   validá-lo lá (biblioteca google-auth-library). Aqui, como é 100% front-end,
   decodificamos localmente só para ler nome/e-mail/foto. */
function handleGoogleCredential(response){
  const payload = decodeJwtPayload(response.credential);
  if(!payload || !payload.email){
    showToast('Não foi possível ler os dados da sua conta Google.');
    return;
  }

  const knownRaw = localStorage.getItem('trifarmas_known_google_emails');
  const known = knownRaw ? JSON.parse(knownRaw) : [];
  const isNewUser = !known.includes(payload.email);
  if(isNewUser){
    known.push(payload.email);
    localStorage.setItem('trifarmas_known_google_emails', JSON.stringify(known));
  }

  state.user = {
    name: payload.name || payload.email.split('@')[0],
    email: payload.email,
    password: null,
    googleAccount: true,
    avatar: payload.picture || `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(payload.name||'G')}&backgroundColor=4285F4&textColor=ffffff`
  };
  state.points = isNewUser ? 50 : 340;
  showToast(isNewUser
    ? 'Conta Google conectada! Você ganhou 50 pontos de boas-vindas 🎉'
    : `Login com Google realizado! Bem-vindo(a) de volta, ${state.user.name.split(' ')[0]}.`);
  enterApp();
}

/* Fallback "conta demo", usado apenas enquanto o GOOGLE_CLIENT_ID acima
   não estiver configurado (veja instruções logo acima). */
function googleAuthDemo(mode){
  const mockNames = ['Ana Beatriz Silva','Carlos Eduardo Souza','Marina Costa Lima','João Pedro Alves'];
  const name = mockNames[Math.floor(Math.random()*mockNames.length)];
  const email = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z]+/g,'.') + '@gmail.com';
  state.user = {
    name, email, password:null, googleAccount:true,
    avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(name)}&backgroundColor=4285F4&textColor=ffffff`
  };
  state.points = mode==='signup' ? 50 : 340;
  showToast(mode==='signup'
    ? 'Conta demo criada! (configure o GOOGLE_CLIENT_ID para login real)'
    : 'Login demo realizado! (configure o GOOGLE_CLIENT_ID para login real)');
  enterApp();
}

/* ---------------- LOGIN / SIGNUP ---------------- */

function doLogin(){
  const email = document.getElementById('login-email').value.trim();
  const pass = document.getElementById('login-pass').value;
  const err = document.getElementById('login-error');
  if(!email || !pass){
    err.textContent = 'Preencha e-mail e senha para continuar.';
    err.classList.remove('hidden');
    return;
  }
  const name = email.split('@')[0];
  state.user = {
    name: name.charAt(0).toUpperCase()+name.slice(1),
    email,
    password: pass,
    googleAccount:false,
    avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(name)}&backgroundColor=2fa85e&textColor=ffffff`
  };
  state.points = 340;
  enterApp();
}

function doSignup(){
  const name = document.getElementById('signup-name').value.trim();
  const email = document.getElementById('signup-email').value.trim();
  const pass = document.getElementById('signup-pass').value;
  if(!name || !email || !pass){ showToast('Preencha todos os campos.'); return; }
  state.user = {
    name, email, password: pass, googleAccount:false,
    avatar: document.getElementById('signup-avatar-preview').src
  };
  state.points = 50;
  showToast('Conta criada! Você ganhou 50 pontos de boas-vindas 🎉');
  enterApp();
}

