function buildNav(){
  const sidebar = document.getElementById('sidebar-nav');
  const bottom = document.getElementById('bottom-nav');
  sidebar.innerHTML = NAV_ITEMS.map(it=>`
    <button class="nav-item" data-tab="${it.id}" onclick="switchTab('${it.id}')">${it.icon}<span>${it.label}</span></button>
  `).join('') + `
    <div class="sidebar-foot" onclick="switchTab('settings')" style="cursor:pointer;">
      <img id="sidebar-avatar" src="" alt="">
      <div>
        <p class="name" id="sidebar-name">—</p>
        <p class="role">Ver perfil</p>
      </div>
    </div>
  `;
  bottom.innerHTML = NAV_ITEMS.map(it=>{
    if(it.center){
      return `<button class="bn-scan" data-tab="${it.id}" onclick="switchTab('${it.id}')">${it.icon}</button>`;
    }
    return `<button class="bn-item" data-tab="${it.id}" onclick="switchTab('${it.id}')">${it.icon}<span>${it.label}</span></button>`;
  }).join('');
}

function switchTab(id){
  state.activeTab = id;
  document.querySelectorAll('.content-inner > section').forEach(s=>s.classList.add('hidden'));
  document.getElementById('tab-'+id).classList.remove('hidden');
  document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active', b.dataset.tab===id));
  document.querySelectorAll('.bn-item').forEach(b=>b.classList.toggle('active', b.dataset.tab===id));

  if(id==='map') initMap();
  if(id==='scanner') startScanner();
  else stopScanner();
  if(id==='calendar') renderCalendar();
  if(id==='orders') renderOrders();
  if(id==='points') renderPoints();
  if(id==='home') renderResults();
}

function toggleTheme(){
  state.theme = state.theme==='light' ? 'dark' : 'light';
  document.body.setAttribute('data-theme', state.theme);
  document.getElementById('settings-theme-switch').classList.toggle('on', state.theme==='dark');
  const icon = document.getElementById('theme-icon');
  icon.innerHTML = state.theme==='dark'
    ? '<path d="M21 12.8A9 9 0 1111.2 3a7 7 0 009.8 9.8z"/>'
    : '<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>';
}

function buildChips(){
  const row = document.getElementById('chip-row');
  const cats = ['Todos', ...CATEGORIES];
  row.innerHTML = cats.map(c=>`<button class="chip ${c==='Todos'?'active':''}" data-cat="${c}" onclick="setCat('${c}')">${c}</button>`).join('');
}
function setCat(cat){
  state.activeCat = cat;
  document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active', c.dataset.cat===cat));
  renderResults();
}

function pharmacyById(id){ return PHARMACIES.find(p=>p.id===id); }

/* ---------------- BUSCA: qualquer remédio, qualquer farmácia ---------------- */

function renderResults(){
  const q = document.getElementById('search-input').value.trim().toLowerCase();
  const wrap = document.getElementById('results-wrap');
  let meds = [...MEDS, ...state.customMeds];
  if(state.activeCat !== 'Todos') meds = meds.filter(m=>m.cat===state.activeCat);
  if(q) meds = meds.filter(m=>m.name.toLowerCase().includes(q));

  let html = '';

  if(meds.length===0){
    html += `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>
      <p>Nenhum remédio encontrado na nossa base ainda.</p>
    </div>`;
  } else {
    html += meds.map(med=>{
      const entries = Object.entries(med.prices).map(([pid,price])=>({...pharmacyById(pid), price}))
        .sort((a,b)=> a.price-b.price || a.dist-b.dist);
      const best = entries[0];
      const nearest3 = [...entries].sort((a,b)=>a.dist-b.dist).slice(0,4);
      const shown = nearest3.some(e=>e.id===best.id) ? nearest3 : [best, ...nearest3.slice(0,3)];

      return `
      <div class="result-card">
        <div class="result-top">
          <div class="result-med">
            <h3>${med.name}</h3>
            <div class="sub">${med.cat} · a partir de <strong>R$ ${best.price.toFixed(2)}</strong></div>
          </div>
          <span class="best-tag">Economize até ${Math.round((1-best.price/Math.max(...entries.map(e=>e.price)))*100)}%</span>
        </div>
        <div class="pharm-list">
          ${shown.map(e=>`
            <div class="pharm-row ${e.id===best.id?'top':''}">
              <div class="pharm-info">
                <div class="pharm-dot">${e.name.charAt(0)}</div>
                <div>
                  <p class="pharm-name">${e.name} ${e.id===best.id?'🏆':''}</p>
                  <p class="pharm-meta">${e.dist.toFixed(1)} km de você</p>
                </div>
              </div>
              <div class="pharm-price">
                <div class="price">R$ ${e.price.toFixed(2)}</div>
                <button class="pharm-buy-btn" onclick="buyMed('${med.id}','${e.id}', ${e.price})">Comprar aqui</button>
              </div>
            </div>
          `).join('')}
        </div>
      </div>`;
    }).join('');
  }

  // se o usuário digitou algo que não existe na base, permite adicionar e comprar mesmo assim
  if(q && !meds.some(m=>m.name.toLowerCase()===q)){
    html += `
    <div class="custom-med-card">
      <p>Não encontrou "<strong>${escapeHtml(document.getElementById('search-input').value.trim())}</strong>" na nossa lista? Você pode adicioná-lo e comprar mesmo assim, independente do preço.</p>
      <button class="btn btn-primary" onclick="addCustomMed()">Adicionar "${escapeHtml(document.getElementById('search-input').value.trim())}" e ver farmácias</button>
    </div>`;
  }

  wrap.innerHTML = html;
}

function escapeHtml(str){
  return str.replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function addCustomMed(){
  const name = document.getElementById('search-input').value.trim();
  if(!name) return;
  // gera preços aleatórios "reais" para todas as farmácias, sem restringir por faixa de preço
  const prices = {};
  PHARMACIES.forEach(p=>{ prices[p.id] = +(8 + Math.random()*90).toFixed(2); });
  const med = { id: 'custom-'+Date.now(), name, cat: 'Outros', prices };
  state.customMeds.push(med);
  document.getElementById('search-input').value = name;
  renderResults();
  showToast(`"${name}" adicionado! Escolha a farmácia que preferir, independente do preço.`);
}

function buyMed(medId, pharmId, price){
  const med = [...MEDS, ...state.customMeds].find(m=>m.id===medId);
  const pharm = pharmacyById(pharmId);
  const earned = Math.max(5, Math.round(price));
  const code = Math.floor(100000 + Math.random()*899999).toString();
  const order = {
    id: Date.now(),
    medName: med.name,
    pharmName: pharm.name,
    price, points: earned, code,
    status: 'Pedido recebido',
    createdAt: new Date()
  };
  state.orders.unshift(order);
  updateOrdersBadge();

  setTimeout(()=> advanceOrder(order.id, 'Em preparação'), 3500);
  setTimeout(()=> advanceOrder(order.id, 'Pronto para retirar'), 8000);

  showModal(
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>',
    'Pedido realizado!',
    `${med.name} reservado na ${pharm.name} por R$ ${price.toFixed(2)}. Acompanhe o status na aba <strong>Pedidos</strong> — os <strong>+${earned} pontos</strong> de cashback só são creditados quando você confirmar a retirada.`
  );
}

function advanceOrder(orderId, status){
  const order = state.orders.find(o=>o.id===orderId);
  if(!order || order.status==='Concluído') return;
  order.status = status;
  if(state.activeTab==='orders') renderOrders();
  updateOrdersBadge();
  if(status==='Pronto para retirar') showToast(`${order.medName} está pronto para retirar na ${order.pharmName}!`);
}

function confirmPickup(orderId){
  const order = state.orders.find(o=>o.id===orderId);
  if(!order || order.status !== 'Pronto para retirar') return;
  order.status = 'Concluído';
  state.points += order.points;
  updatePointsUI();
  renderOrders();
  updateOrdersBadge();
  showToast(`Pedido concluído! +${order.points} pontos creditados 🎉`);
}

function updateOrdersBadge(){
  const readyCount = state.orders.filter(o=>o.status==='Pronto para retirar').length;
  document.querySelectorAll('[data-tab="orders"] .nav-badge, [data-tab="orders"] .bn-dot').forEach(el=>el.remove());
  if(readyCount===0) return;
  const sideBtn = document.querySelector('.nav-item[data-tab="orders"]');
  if(sideBtn) sideBtn.insertAdjacentHTML('beforeend', `<span class="nav-badge">${readyCount}</span>`);
  const bnBtn = document.querySelector('.bn-item[data-tab="orders"]');
  if(bnBtn) bnBtn.insertAdjacentHTML('beforeend', `<span class="bn-dot"></span>`);
}

const ORDER_STEPS = ['Pedido recebido','Em preparação','Pronto para retirar','Concluído'];
function renderOrders(){
  const wrap = document.getElementById('orders-list');
  if(state.orders.length===0){
    wrap.innerHTML = `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 8l8-4 8 4v8l-8 4-8-4V8z"/><path d="M4 8l8 4 8-4M12 12v8"/></svg>
      <p>Você ainda não fez nenhum pedido. Compare preços na aba Buscar e reserve seu remédio.</p>
    </div>`;
    return;
  }
  const badgeClass = {
    'Pedido recebido':'status-received', 'Em preparação':'status-preparing',
    'Pronto para retirar':'status-ready', 'Concluído':'status-done'
  };
  wrap.innerHTML = state.orders.map(o=>{
    const stepIdx = ORDER_STEPS.indexOf(o.status);
    const time = o.createdAt.toLocaleDateString('pt-BR', {day:'2-digit', month:'short'});
    return `
    <div class="order-card">
      <div class="order-top">
        <div>
          <h3>${o.medName}</h3>
          <div class="sub">${o.pharmName} · pedido em ${time}</div>
        </div>
        <span class="status-badge ${badgeClass[o.status]}">${o.status}</span>
      </div>
      <div class="order-track">
        ${ORDER_STEPS.map((s,i)=>`
          <div class="otrack-step ${i<=stepIdx?'done':''}">
            <div class="otrack-line"></div>
            <div class="otrack-dot"></div>
            <div class="otrack-label">${s}</div>
          </div>
        `).join('')}
      </div>
      <div class="order-code">
        <span>Código de retirada</span>
        <b>${o.code}</b>
      </div>
      ${o.status==='Pronto para retirar' ? `<button class="confirm-pickup-btn" onclick="confirmPickup(${o.id})">Confirmar retirada e receber pontos</button>` : ''}
      ${o.status==='Concluído' ? `<div class="order-earned">✓ +${o.points} pontos creditados</div>` : ''}
    </div>`;
  }).join('');
}

/* ---------------- SCANNER ---------------- */

let scannerStream = null;
async function startScanner(){
  const video = document.getElementById('scanner-video');
  const status = document.getElementById('scanner-status');
  buildScannerMockList();
  try{
    scannerStream = await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});
    video.srcObject = scannerStream;
    status.textContent = 'Aponte para o código de barras ou a caixa do remédio.';
  }catch(e){
    status.textContent = 'Câmera indisponível — escolha um remédio abaixo ou tente novamente.';
  }
}
function stopScanner(){
  if(scannerStream){ scannerStream.getTracks().forEach(t=>t.stop()); scannerStream=null; }
}
function buildScannerMockList(){
  document.getElementById('scanner-mock-list').innerHTML = MEDS.slice(0,6).map(m=>
    `<button class="chip" onclick="scanResult('${m.id}')">${m.name.split(' ')[0]}</button>`
  ).join('');
}
function mockCapture(){
  const med = MEDS[Math.floor(Math.random()*MEDS.length)];
  scanResult(med.id);
}
function scanResult(medId){
  const med = MEDS.find(m=>m.id===medId);
  showToast(`Identificado: ${med.name}`);
  switchTab('home');
  document.getElementById('search-input').value = med.name;
  setCat('Todos');
  renderResults();
}

/* ---------------- MAPA REAL (Google Maps) ---------------- */

let mapInitialized = false;

function initMap(){
  if(!mapInitialized){
    mapInitialized = true;
    requestMapLocation();
  }
}

function loadMapAt(lat, lng){
  const frame = document.getElementById('gmap-frame');
  const src = `https://www.google.com/maps?q=farm%C3%A1cia&ll=${lat},${lng}&z=15&output=embed`;
  frame.src = src;
}

function requestMapLocation(){
  const status = document.getElementById('map-status');
  status.textContent = 'Obtendo sua localização…';
  status.classList.remove('hidden');
  if(!('geolocation' in navigator)){
    status.textContent = 'Localização indisponível — mostrando região padrão.';
    loadMapAt(-23.5505, -46.6333); // fallback: São Paulo
    setTimeout(()=> status.classList.add('hidden'), 2500);
    return;
  }
  navigator.geolocation.getCurrentPosition(
    pos=>{
      loadMapAt(pos.coords.latitude, pos.coords.longitude);
      status.textContent = 'Localização encontrada!';
      setTimeout(()=> status.classList.add('hidden'), 1800);
    },
    err=>{
      status.textContent = 'Não foi possível obter sua localização — mostrando região padrão.';
      loadMapAt(-23.5505, -46.6333); // fallback: São Paulo
      setTimeout(()=> status.classList.add('hidden'), 2500);
    },
    {enableHighAccuracy:true, timeout:8000}
  );
}

/* ---------------- CALENDÁRIO ---------------- */

const DOW = ['D','S','T','Q','Q','S','S'];
const MONTHS = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];

function calShiftMonth(delta){
  state.calMonth += delta;
  if(state.calMonth<0){ state.calMonth=11; state.calYear--; }
  if(state.calMonth>11){ state.calMonth=0; state.calYear++; }
  renderCalendar();
}

function renderCalendar(){
  document.getElementById('cal-month-label').textContent = `${MONTHS[state.calMonth]} ${state.calYear}`;
  const grid = document.getElementById('cal-grid');
  const firstDow = new Date(state.calYear, state.calMonth, 1).getDay();
  const daysInMonth = new Date(state.calYear, state.calMonth+1, 0).getDate();
  let html = DOW.map(d=>`<div class="cal-dow">${d}</div>`).join('');
  for(let i=0;i<firstDow;i++) html += `<div class="cal-day muted"></div>`;
  for(let d=1; d<=daysInMonth; d++){
    const hasRem = state.reminders.some(r=> r.day===d && r.month===state.calMonth && r.year===state.calYear);
    const sel = state.calSelectedDay===d;
    html += `<div class="cal-day ${sel?'selected':''} ${hasRem?'has-rem':''}" onclick="calSelectDay(${d})">${d}</div>`;
  }
  grid.innerHTML = html;
  renderReminderList();
}
function calSelectDay(d){ state.calSelectedDay = d; renderCalendar(); }

function addReminder(){
  const med = document.getElementById('rem-med').value.trim();
  const time = document.getElementById('rem-time').value;
  if(!med || !time){ showToast('Preencha o remédio e o horário.'); return; }
  state.reminders.push({
    id: Date.now(), med, time,
    day: state.calSelectedDay, month: state.calMonth, year: state.calYear
  });
  document.getElementById('rem-med').value='';
  renderCalendar();
  showToast('Lembrete definido com sucesso!');
}
function removeReminder(id){
  state.reminders = state.reminders.filter(r=>r.id!==id);
  renderCalendar();
}
function renderReminderList(){
  const list = state.reminders
    .filter(r=>r.month===state.calMonth && r.year===state.calYear)
    .sort((a,b)=> a.day-b.day || a.time.localeCompare(b.time));
  const el = document.getElementById('rem-list');
  if(list.length===0){ el.innerHTML = `<div class="empty-state" style="padding:24px 10px;"><p>Nenhum lembrete este mês ainda.</p></div>`; return; }
  el.innerHTML = list.map(r=>`
    <div class="rem-item">
      <div class="rem-time">${r.time}</div>
      <div class="rem-info"><p>${r.med}</p><span>Dia ${r.day} de ${MONTHS[r.month]}</span></div>
      <button class="rem-del" onclick="removeReminder(${r.id})"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a1 1 0 011-1h6a1 1 0 011 1v2m2 0v14a1 1 0 01-1 1H7a1 1 0 01-1-1V6h12z"/></svg></button>
    </div>
  `).join('');
}

/* ---------------- PONTOS ---------------- */

const REWARDS = [
  {id:'r1', name:'R$5 de desconto', desc:'Em qualquer analgésico', cost:100},
  {id:'r2', name:'R$10 de desconto', desc:'Em qualquer antibiótico', cost:200},
  {id:'r3', name:'15% off', desc:'Em produtos de dermocosmética', cost:280},
  {id:'r4', name:'Frete grátis', desc:'Na retirada expressa', cost:80},
  {id:'r5', name:'R$20 de desconto', desc:'Em compras acima de R$100', cost:400},
];
function updatePointsUI(){
  document.getElementById('topbar-points').textContent = state.points;
  document.getElementById('points-big').textContent = state.points;
  document.getElementById('points-value').textContent = (state.points*0.05).toFixed(2).replace('.',',');
}
function renderPoints(){
  updatePointsUI();
  document.getElementById('reward-grid').innerHTML = REWARDS.map(r=>`
    <div class="reward-card">
      <h4>${r.name}</h4>
      <p>${r.desc}</p>
      <div class="reward-cost">${r.cost} pts</div>
      <button class="reward-btn" ${state.points<r.cost?'disabled':''} onclick="redeem('${r.id}')">Resgatar</button>
    </div>
  `).join('');
}
function redeem(id){
  const r = REWARDS.find(x=>x.id===id);
  if(state.points<r.cost) return;
  state.points -= r.cost;
  updatePointsUI();
  renderPoints();
  showToast(`Resgatado: ${r.name}!`);
}

/* ---------------- CONFIGURAÇÕES / SENHA ---------------- */

function saveSettings(){
  const errBox = document.getElementById('settings-pass-error');
  errBox.classList.add('hidden');

  state.user.name = document.getElementById('settings-name').value.trim() || state.user.name;
  state.user.email = document.getElementById('settings-email').value.trim() || state.user.email;

  const currentInput = document.getElementById('settings-pass-current').value;
  const newPass = document.getElementById('settings-pass').value;
  const confirmPass = document.getElementById('settings-pass-confirm').value;

  if(newPass || confirmPass || currentInput){
    if(state.user.googleAccount){
      errBox.textContent = 'Sua conta usa login do Google — a senha é gerenciada pela sua Conta Google.';
      errBox.classList.remove('hidden');
      return;
    }
    if(!currentInput){
      errBox.textContent = 'Digite sua senha atual para confirmar a alteração.';
      errBox.classList.remove('hidden');
      return;
    }
    if(currentInput !== state.user.password){
      errBox.textContent = 'Senha atual incorreta. Tente novamente.';
      errBox.classList.remove('hidden');
      return;
    }
    if(!newPass){
      errBox.textContent = 'Digite a nova senha que deseja usar.';
      errBox.classList.remove('hidden');
      return;
    }
    if(newPass !== confirmPass){
      errBox.textContent = 'A confirmação da nova senha não confere.';
      errBox.classList.remove('hidden');
      return;
    }
    state.user.password = newPass;
    document.getElementById('settings-pass-current').value='';
    document.getElementById('settings-pass').value='';
    document.getElementById('settings-pass-confirm').value='';
    showToast('Senha alterada com sucesso!');
  } else {
    showToast('Dados atualizados com sucesso!');
  }

  document.getElementById('home-greeting').textContent = `Olá, ${state.user.name.split(' ')[0]}! Pesquise um remédio e veja as farmácias mais perto de você.`;
  document.getElementById('sidebar-name').textContent = state.user.name;
  document.getElementById('sidebar-avatar').src = state.user.avatar;
}

/* ---------------- TOASTS / MODAIS ---------------- */

let toastTimer=null;
function showToast(msg){
  const t = document.getElementById('toast');
  t.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg> ${msg}`;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=> t.classList.remove('show'), 3200);
}
function showModal(iconSvg, title, bodyHtml){
  const back = document.createElement('div');
  back.className='modal-back';
  back.innerHTML = `<div class="modal-box">
    <div class="icon-circle">${iconSvg}</div>
    <h3>${title}</h3>
    <p>${bodyHtml}</p>
    <button class="btn btn-primary" style="max-width:100%;">Entendi</button>
  </div>`;
  back.querySelector('button').onclick = ()=> back.remove();
  back.onclick = (e)=>{ if(e.target===back) back.remove(); };
  document.body.appendChild(back);
}

